fn solve(input: Vec<char>) -> Vec<char> {
    // Convert the input Vec<char> to a String for easier manipulation
    let input_str: String = input.iter().collect();
    
    // Check the prefix "AtCoder "
    if !input_str.starts_with("AtCoder ") {
        return Vec::new(); // Invalid input, return empty Vec
    }
    
    // Find the first space after "AtCoder "
    let name_start = "AtCoder ".len();
    let name_end = input_str[name_start..].find(' ').unwrap_or_else(|| input_str.len() - name_start) + name_start;
    
    // Extract the name
    let name = &input_str[name_start..name_end];
    
    // Check if the name is valid
    if name.is_empty() || !name.chars().next().unwrap().is_uppercase() {
        return Vec::new(); // Invalid name, return empty Vec
    }
    
    // Check if the next part is "Contest\n"
    let contest_start = name_end + 1; // Skip the space after the name
    if !input_str[contest_start..].starts_with("Contest\n") {
        return Vec::new(); // Invalid format, return empty Vec
    }
    
    // Get the initial of the name
    let initial = name.chars().next().unwrap();
    
    // Build the result
    build_result(initial)
}

fn build_result(ch: char) -> Vec<char> {
    let mut result = Vec::new();
    result.push('A');
    result.push(ch);
    result.push('C');
    result.push('\n');
    result
}

// Example usage
fn main() {
    let input = "AtCoder Alice Contest\n".chars().collect::<Vec<char>>();
    let result = solve(input);
    let output: String = result.iter().collect();
    println!("{}", output); // Should print "AA\n"
}